CREATE TABLE "frequency_counts" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "updated_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP, "channel" character varying NOT NULL, "destination" character varying NOT NULL, "counted_at" timestamptz NOT NULL, "outbound_message_id" bigint NOT NULL, "workspace_id" bigint NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "frequency_counts_outbound_messages_frequency_counts" FOREIGN KEY ("workspace_id", "outbound_message_id") REFERENCES "outbound_messages" ("workspace_id", "id") ON UPDATE NO ACTION ON DELETE CASCADE, CONSTRAINT "frequency_counts_workspaces_frequency_counts" FOREIGN KEY ("workspace_id") REFERENCES "workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "frequency_counts_channel_check" CHECK ((channel)::text = ANY ((ARRAY['email'::character varying, 'telegram'::character varying, 'sms'::character varying])::text[])));
-- create index "frequency_counts_workspace_channel_destination_counted_at" to table: "frequency_counts"
